public class Main {
    static int calc() {
        int x = 1;
        try {
            x = 2;
            return x;
        } finally {
            x = 3;
            System.out.println("finally x=" + x);
        }
    }
    public static void main(String[] args) {
        int r = calc();
        System.out.println("r=" + r);
    }
}
